"use client";

import { useLocale, useTranslations } from "next-intl";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useRouter } from "next/navigation";

export default function LanguageSwitcher() {
  const locale = useLocale();
  const pathname = usePathname();
  const t = useTranslations("components");
  const router = useRouter();

  const switchLocale = (newLocale: string) => {
    const path = pathname.split("/").at(-1);
    console.log(`/${newLocale}/${path}`)
    router.push(`/${newLocale}/${path}`);
  };

  const languages = [
    { code: "en", name: t("localeSwitcher.english") },
    { code: "de", name: t("localeSwitcher.german") },
    { code: "es", name: t("localeSwitcher.spanish") },
  ];

  return (
    <div className="languageSwitcher">
      {languages.map(({ code, name }) => (
        <Link
          key={code}
          href={pathname}
          locale={code}
          onClick={() => switchLocale(code)}
          className={`languageSwitcher__link ${
            locale === code ? "languageSwitcher__link--active" : ""
          }`}
        >
          {name}
        </Link>
      ))}
    </div>
  );
}
